Given two integer arrays of the same length, arr[] and index[], the task is to reorder the elements in arr[] such that after reordering, each element from arr[i] moves to the position index[i]. The new arrangement reflects the values being placed at their target indices, as described by index[] array.Example: Input: arr[] = [10, 11, 12], index[] = [1, 0, 2]Output: 11 10 12Explanation: 10 moves to position 1, 11 to 0, and 12 stays at 2.Input: arr[] = [1, 2, 3, 4], index[] = [3, 2, 0, 1]Output: 3 4 2 1Explanation: 1 moves to 3, 2 to 2, 3 to 0, 4 to 1.Input: arr[] = [50, 40, 70, 60, 90], index[] = [3,  0,  4,  1,  2]Output: 40 60 90 50 70Table of Content[Naive Approach] Using Sorting - O(n*log(n)) Time and O(n) Space[Better Approach] Using an Auxiliary Array - O(n) Time and O(n) Space[Expected Approach - 1] Using Cyclic Sort - O(n) Time and O(1) Space[Expected Approach - 2] Using Mathematics - O(n) Time and O(1) Space[Naive Approach] Using Sorting - O(n*log(n)) Time and O(n) SpaceThe idea is to pair each element in arr[] with its target position from index[] as a 2D array. These pairs are then sorted by index, which arranges elements in the order they should appear in the final array. After sorting, we extract only the values (second part of each pair) to build the reordered array.
            C++

    // C++ program to reorder arr[] using index[]
// using Naive approach
#include <bits/stdc++.h>
using namespace std;

// Function to reorder arr based on index
void reorderArray(vector<int> &arr, 
                  vector<int> &index) {

    // Pair each element with its target index
    vector<vector<int>> paired;

    for (int i = 0; i < arr.size(); i++) {
        paired.push_back({index[i], arr[i]});
    }

    // Sort the pairs by index
    sort(paired.begin(), paired.end());

    // Rearrange arr based on sorted pairs
    for (int i = 0; i < arr.size(); i++) {
        arr[i] = paired[i][1];
    }

}

// Driver code
int main() {

    vector<int> arr = {10, 11, 12};
    vector<int> index = {1, 0, 2};

    reorderArray(arr, index);

    // Print the updated array
    for (int i = 0; i < arr.size(); i++) {
        cout << arr[i] << " ";
    }

    return 0;
}


