        int[] arr = {10, 11, 12};
        int[] index = {1, 0, 2};

        reorderArray(arr, index);

        // Print the updated array
        for (int i = 0; i < arr.length; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}


